    #[napi]
    pub fn vault_recall(
        &self,
        query: String,
        effort: Option<String>,
        scope: Option<NapiRecallScope>,
        limit: Option<f64>,
        format: Option<String>,
        as_of: Option<f64>,
        deadline_ms: Option<f64>,
        media: Option<NapiRecallMedia>,
        query_affect: Option<NapiQueryAffect>,
    ) -> napi::Result<NapiMemoryPack> {
        let effort = oneiron_remote::parse_effort(effort.as_deref().unwrap_or("medium"))
            .map_err(facade_error)?;
        let scope = recall_scope_to_engine(scope);
        let limit = limit
            .map(limit_to_engine)
            .transpose()
            .map_err(facade_error)?
            .unwrap_or(10);

        let as_of = as_of
            .map(|value| oneiron_remote::check_unix_seconds("as_of", value))
            .transpose()
            .map_err(facade_error)?;
        let deadline_ms = deadline_ms
            .map(oneiron_remote::check_deadline_ms_number)
            .transpose()
            .map_err(facade_error)?;
        let media = media
            .map(recall_media_to_engine)
            .transpose()
            .map_err(facade_error)?;
        let query_affect = query_affect.map(query_affect_to_engine);
        let output = self
            .inner
            .vault_recall(
                &query,
                effort,
                &scope,
                limit,
                format.as_deref(),
                as_of,
                deadline_ms,
                media,
                query_affect,
            )
            .map_err(facade_error)?;
        memory_pack_from_engine(output).map_err(boundary_error)
    }
